-- public.trait_worth(p_traits text[])
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.trait_worth(p_traits text[])
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select string_agg(s.say, ', ' order by s.ord)
  from (
    select cd.ord, case when cd.adds then trait_fig(x.n::real, true) else pct_say(x.m) end || ' ' || cd.label as say,
           cd.adds, x.n, x.m
    from (
      select e.channel, sum(e.mul order by e.trait) as n,
             case when bool_or(e.mul = 0) then 0 else exp(sum(ln(nullif(e.mul, 0)) order by e.trait)) end as m
      from unnest(coalesce(p_traits, '{}')) u(id)
      join trait_effect e on e.trait = u.id
      group by e.channel
    ) x
    join channel_def cd on cd.id = x.channel
  ) s
  where case when s.adds then s.n <> 0 else abs(s.m - 1) >= 0.005 end
$function$
